import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick check for clinical/cohort variables
    clinical_vars = [i for i, t in enumerate(feats.types) if t in ('clinical', 'cohort')]

    if not clinical_vars:
        # No clinical variables; use top features by t-statistic
        drivers = ()
        columns = []
        products = []
        loadings = {}

        # Just use top features based on t-test - limit computation
        t_stats = []
        for i, fid in enumerate(feats.ids):
            if feats.types[i] in ('copy_number', 'expression'):
                try:
                    t_stat = np.abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic)
                    t_stats.append((t_stat, i, fid))
                except:
                    continue

        t_stats.sort(reverse=True)
        for _, i, fid in t_stats[:5]:  # Top 5 features only
            columns.append(fid)
            loadings[fid] = feats.x[:, i].mean()

        return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

    # Find strongest clinical variable quickly
    max_corr = 0
    best_clinical = None
    for i in clinical_vars:
        corr = np.abs(np.corrcoef(feats.x[:, i], feats.y)[0, 1])
        if corr > max_corr:
            max_corr = corr
            best_clinical = feats.ids[i]

    # Use best clinical variable as driver if strong enough
    if max_corr > 0.1:
        drivers = (best_clinical,)
    else:
        drivers = ()

    # Quick duplicate removal
    to_remove = set()
    # Only check a subset of pairs to save time
    sample_indices = list(range(0, len(feats.ids), 5))  # Sample every 5th feature
    for i in sample_indices:
        for j in sample_indices:
            if i >= j:
                continue
            if abs(np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]) >= 0.6:
                to_remove.add(feats.ids[j])

    filtered_ids = [fid for fid in feats.ids if fid not in to_remove]

    # Select features with strong t-statistics - very limited
    columns = []
    products = []
    loadings = {}

    # Add top features based on t-test - very limited
    t_stats = []
    for i, fid in enumerate(filtered_ids):
        if feats.types[i] in ('copy_number', 'expression'):
            try:
                t_stat = np.abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic)
                t_stats.append((t_stat, i, fid))
            except:
                continue

    t_stats.sort(reverse=True)
    for _, i, fid in t_stats[:3]:  # Top 3 features only
        columns.append(fid)
        loadings[fid] = feats.x[:, i].mean()

    # Add some product terms for top correlated pairs - very limited
    correlated_pairs = [
        ('LME4', 'ULN1'), ('WTGO11A', 'AOG19'), ('CDHD17', 'AOG19'),
        ('AOG19', 'KBJ18'), ('EWWM15', 'AOG19'), ('NQHO6', 'JSKR5')
    ]

    for a, b in correlated_pairs:
        if a in filtered_ids and b in filtered_ids:
            products.append((a, b))
            if len(products) >= 2:  # Limit products
                break

    # Limit drivers
    if len(drivers) > MAX_DRIVERS:
        drivers = drivers[:MAX_DRIVERS]

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

